INSERT INTO `creature_template` (`entry`, `difficulty_entry_1`, `difficulty_entry_2`, `difficulty_entry_3`, `KillCredit1`, `KillCredit2`, `name`, `subname`, `IconName`, `gossip_menu_id`, `minlevel`, `maxlevel`, `faction`, `npcflag`, `speed_walk`, `speed_run`, `rank`, `dmgschool`, `DamageModifier`, `BaseAttackTime`, `RangeAttackTime`, `BaseVariance`, `RangeVariance`, `unit_class`, `unit_flags`, `unit_flags2`, `family`, `type`, `type_flags`, `lootid`, `pickpocketloot`, `skinloot`, `PetSpellDataId`, `VehicleId`, `mingold`, `maxgold`, `AIName`, `MovementType`, `HoverHeight`, `HealthModifier`, `ManaModifier`, `ArmorModifier`, `ExperienceModifier`, `RacialLeader`, `movementId`, `RegenHealth`, `flags_extra`, `ScriptName`, `VerifiedBuild`)
SELECT `entry`+@OFF, `difficulty_entry_1`, `difficulty_entry_2`, `difficulty_entry_3`, `KillCredit1`, `KillCredit2`, `name`, `subname`, `IconName`, `gossip_menu_id`, `minlevel`, `maxlevel`, `faction`, `npcflag`, `speed_walk`, `speed_run`, `rank`, `dmgschool`, `DamageModifier`, `BaseAttackTime`, `RangeAttackTime`, `BaseVariance`, `RangeVariance`, `unit_class`, `unit_flags`, `unit_flags2`, `family`, `type`, `type_flags`, IF(`lootid`=0, 0, `lootid`+@OFF), `pickpocketloot`, `skinloot`, `PetSpellDataId`, `VehicleId`, `mingold`, `maxgold`, `AIName`, `MovementType`, `HoverHeight`, `HealthModifier`, `ManaModifier`, `ArmorModifier`, `ExperienceModifier`, `RacialLeader`, `movementId`, `RegenHealth`, `flags_extra`, `ScriptName`, `VerifiedBuild`
FROM `cata_world`.`creature_template`
WHERE `entry` IN (35761,35762,36130);

-- cata_world.creature_template_model has no DisplayScale column, and it stores
-- Probability 0 on single-model rows -- forced to 1 here so ChooseDisplayId
-- always has a weighted candidate.
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (3635761,3635762,3636130);
INSERT INTO `creature_template_model` (`CreatureID`, `Idx`, `CreatureDisplayID`, `DisplayScale`, `Probability`, `VerifiedBuild`) VALUES
(3635761, 0,   328, 1, 0, 15595),
(3635761, 1, 27823, 1, 1, 15595),
(3635762, 0, 11686, 1, 1, 15595),
(3636130, 0, 26650, 1, 1, 15595);

-- 36130 is a hostile (faction 14) elemental the player summons and kills.
-- Cata ships it at level 17; quest 14324 is MinLevel 78 here and its direct
-- Azshara neighbour 3636131 "Vile Splash" sits at 83-85 after the round-48
-- band re-level, so match that rather than leaving a level-17 outlier.
-- 3635761/3635762 stay at their Cata levels: they are summon bunnies.
UPDATE `creature_template` SET `minlevel` = 83, `maxlevel` = 85 WHERE `entry` = 3636130;

-- Verbatim from cata_world; references 45009/24731 and items 1206, 1210,
-- 49174, 55974, 55982 all already exist here.
DELETE FROM `creature_loot_template` WHERE `Entry` = 3636130;
INSERT INTO `creature_loot_template` (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment`)
SELECT `Entry`+@OFF, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment`
FROM `cata_world`.`creature_loot_template`
WHERE `Entry` = 36130;


-- ---------------------------------------------------------------------
-- 3. BagFamily bit 17 -- the Cataclysm Cooking Bag
-- ---------------------------------------------------------------------
-- ItemBagFamily.dbc on 3.3.5 has ids 0..16, so 65536 (= bit for id 17, the
-- Cooking Bag added in Cataclysm) has no row.  The core already strips the bit
-- at load; this just clears it at the source so the five lines stop repeating.
-- Verified this is the complete set: no other item has a bit above 16 set.
UPDATE `item_template` SET `BagFamily` = `BagFamily` & ~65536
WHERE `entry` IN (49365, 58261, 63275, 67229, 67272);


-- ---------------------------------------------------------------------
-- 4. Item 49533 "Ironwrought Key" -- Map 256
-- ---------------------------------------------------------------------
-- Map 256 is a 4.3.4 sniff artifact with no Map.dbc row here, and unlike the
-- spell and bag-family cases the core does NOT clear it -- it only logs.  The
-- key drops from 3636636/3636637 (Twilight Dragon Hunter) on map 750, so drop
-- the restriction rather than inventing one.  49533 is the only item in the
-- table with an unresolvable Map; every other non-zero value is a real WotLK
-- map.
UPDATE `item_template` SET `Map` = 0 WHERE `entry` = 49533;


